    }
  }

  if (!store.pendingRevalidatedTags) {
    store.pendingRevalidatedTags = []
  }

  for (const tag of tags) {
    if (!store.pendingRevalidatedTags.includes(tag)) {
      store.pendingRevalidatedTags.push(tag)
    }
  }

